private void resetXrayForEngineChange() {
    boolean awaiting = mLiveAuto.isAwaitingPlayback();
    boolean resolved = mLiveAuto.hasResolvedRoute();
    resetXrayForPlaybackChange();
    if (!awaiting) return;
    restoreAutoXrayMetadata();
    // An unresolved URL can still complete normally. A resolved result
    // held for START was just retired, so submit a fresh resolver request
    // without auto-enabling Xray. Delivery is posted to main, after the
    // dialog has applied the newly selected ordinary engine.
    if (resolved) mLive.resumeChannelAfterXrayStart();
}

@Override
protected void onXrayBindingReplaced() {
    if (mLiveAuto.isAwaitingPlayback()) {
        // A queued resolver result must not start directly after the next
        // owner claim has reset this automatic policy. Re-evaluate it on
        // return instead, using the currently saved rules.
        mXrayAutoReclaimPending = true;
        mLive.retirePendingPlayback();
        mViewModel.cancelPlaybackUrl();
    }
    resetXrayForPlaybackChange();
}

private void resumeRetiredAutoRequest() {
    if (!mXrayAutoReclaimPending || !isBindingOwner()) return;
    // Keep the retired-auto marker visible to prepare until it decides
    // whether to restore direct metadata or suppress it for a new match.
    mLive.refresh();
    mXrayAutoReclaimPending = false;
}

