public void startPlayback(Result result, long position, MediaMetadata metadata) {
        if (isFinishing() || isDestroyed() || !isBindingOwner()) return;
        mInput.cancelSeek();
        String url = result.getRealUrl();
        if (isWebPlayback(result)) {
            boolean automatic = mLiveAuto.isAutomatic();
            resetXrayForPlaybackChange();
            startResolvedLive(result, position, metadata);
            if (automatic) restoreAutoXrayMetadata();
            return;
        }
        mXray.mediaUrlChanged(url);
        boolean automatic = mLiveAuto.isAutomatic();
        if (mLiveAuto.deferResolved(mXray, url, () -> startResolvedLive(result, position, metadata))) return;
        // A retained Core must validate each station's own resolved URL first.
        if (mLiveAuto.isAutomatic()) refreshXrayAwareMetadata();
        startResolvedLive(result, position, metadata);
        if (automatic && !mLiveAuto.isAutomatic()) restoreAutoXrayMetadata();
    }

    private void startResolvedLive(Result result, long position, MediaMetadata metadata) {
        if (isFinishing() || isDestroyed() || !isBindingOwner()) return;
        mPlaybackKey = result.getRealUrl();
        if (startWebPlayback(result)) return;
        startPlayer(mPlaybackKey, result, false, getHome().getTimeout(), position, metadata);
    }

