        mInput.cancelSeek();
        super.onStop();
        if (PlayerSetting.isBackgroundOff()) mClock.stop();
    }

protected void onStop() {
        mInput.cancelSeek();
        boolean preservePlayback = !isFinishing()
                && !PlayerSetting.isBackgroundOff()
                && hasNativePlaybackSession();
        mLiveAuto.suspend(!isFinishing() && isBindingOwner() && !hasNativePlaybackSession());
        mXrayPendingChannelResume = false;
        mXrayStartedFromExistingPlayback = false;
        mXrayRefreshMetadataOnDetach = false;
        if (mXray != null) mXray.stop(preservePlayback);
        super.onStop();
        if (PlayerSetting.isBackgroundOff()) mClock.stop();
    }

protected void onDestroy() {
        mInput.cancelSeek();
        mClock.release();
        if (isBindingOwner() && isOwner()) Source.get().exit();
        App.removeCallbacks(mR0, mR1, mR2, mR3, mR4);
        super.onDestroy();
    }

protected void onDestroy() {
        mInput.cancelSeek();
        clearArtworkTarget();
        mLiveAuto.reset();
        if (mXray != null) mXray.close();
        mClock.release();
        if (isBindingOwner() && isOwner()) Source.get().exit();
        App.removeCallbacks(mR0, mR1, mR2, mR3, mR4);
        super.onDestroy();
    }
